// Connection settings come from the n8n container environment (docker-compose.yml);
// the defaults work with the demo data. The webhook payload (if any) is kept as "trigger".
const e = $env;
const first = $input.first().json;
return [{ json: {
  api: (e.FM_API_URL || 'http://backend:8000/api/v1').replace(/\/$/, ''),
  email: e.FM_API_EMAIL || 'cfo@futuremirror.demo',
  password: e.FM_API_PASSWORD || 'FutureMirror!2026',
  tenant: e.FM_API_TENANT || 'nile-engineering',
  alertTo: e.FM_ALERT_EMAIL || 'approvers@example.com',
  hrTo: e.FM_HR_EMAIL || 'hr@example.com',
  from: e.FM_FROM_EMAIL || 'future-mirror@example.com',
  appUrl: (e.FM_APP_URL || 'http://localhost:8080').replace(/\/$/, ''),
  trigger: first.body || {},
}}];

// Sent by the platform when a strategy is submitted for approval.
const t = $('Settings').first().json.trigger;
const app = $('Settings').first().json.appUrl;
if (!t.idempotency_key) return [];  // not from Future Mirror
const roles = Array.isArray(t.roles) ? t.roles.join(', ') : (t.roles || 'approvers');
return [{ json: { subject: `Decision awaiting your approval: ${t.decision || ''}`,
  text: `A strategy was submitted for approval.

Decision: ${t.decision || ''}
Approval request: ${t.approval_request_id || ''}
Required roles: ${roles}

Review it in Future Mirror AI: ${app}/approvals
This notification performs no business action.` } }];
